import { Component, Prop, h, Host, ComponentInterface, Element } from '@stencil/core';
import classnames from 'classnames';
import { t } from '@src/shared/i18n';
import { badgeMessages } from '@fe-infra/keystone-locales';
import { Slot, Slots } from '@src/framework/decorators';

const prefix = 'badge';

type BadgeVariant = 'support' | 'neutral' | 'success' | 'error' | 'info';
type BadgePlacement = 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end';
type BadgeOffset = [number, number];

/**
 * @slot default - Slot for the anchor content the badge attaches to, such as an avatar, icon, or other inline element.
 * @slot content - Renders custom badge indicator markup and takes precedence over `count`, `new`, and `dot`.
 * @part base - Wraps the default-slot anchor content and positioned badge indicator.
 */
@Component({
  tag: 'ks-badge',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsBadge implements ComponentInterface {
  @Element() el!: HTMLKsBadgeElement;
  /** Displays a numeric value inside the badge indicator. The rendered value is constrained by `overflowCount` and `showZero`. */
  @Prop() count?: number;
  /** Caps the rendered numeric value as `${overflowCount}+` when `count` exceeds this threshold. */
  @Prop() overflowCount = 99;
  /** Keeps the badge visible when `count` is `0`. */
  @Prop() showZero = false;
  /** Renders simple text content inside the badge indicator. Use the `content` slot for richer markup. */
  @Prop() content?: string;
  /** Displays the localized `New` label when no custom content or count is rendered. */
  @Prop() new = false;
  /** Displays a dot indicator when no custom content, count, or `new` label is rendered. */
  @Prop() dot = false;
  /** Controls the badge tone. Can be one of the following values: `"error"`, `"info"`, `"neutral"`, `"success"`, or `"support"`. */
  @Prop() variant: BadgeVariant = 'error';
  /** Positions the badge relative to the content passed into the default slot. Can be one of the following values: `"top-start"`, `"top-end"`, `"bottom-start"`, or `"bottom-end"`. */
  @Prop() placement: BadgePlacement = 'top-end';
  /** Visually mutes the rendered badge indicator. */
  @Prop() disabled = false;
  /** Offsets the badge indicator by `[horizontal, vertical]` pixels from its anchored placement. */
  @Prop() offset?: BadgeOffset;

  @Slot({ slotname: '_default' }) private defaultSlot?: Slots;
  @Slot({ slotname: 'content' }) private contentSlot?: Slots;

  /** Address well-defined content before ambiguous ones */
  private get type() {
    if (this.content || this.contentSlot?.length) {
      return 'content';
    } else if (
      (typeof this.count === 'number' || typeof this.count === 'string') &&
      ((this.count && Number(this.count)) || (this.showZero && String(this.count) === '0'))
    ) {
      return 'count';
    } else if (this.new) {
      return 'new';
    } else if (this.dot) {
      return 'dot';
    } else {
      return null;
    }
  }

  render() {
    const prefixsup = `${prefix}__sup`;
    const classes = classnames([
      `${prefixsup}`,
      `${prefixsup}--${this.type === 'new' ? 'content' : this.type}`,
      `${prefixsup}--color-${this.variant}`,
      { [`${prefixsup}--alone`]: !this.defaultSlot?.length },
      { [`${prefixsup}--dir-${this.placement}`]: Boolean(this.defaultSlot?.length) },
    ]);
    const style = this.offset
      ? {
          '--badge-offset-horizontal': `${this.offset[0]}px`,
          '--badge-offset-vertical': `${this.offset[1]}px`,
        }
      : undefined;

    return (
      <Host class="KsBadge">
        <div part="base" class={`${prefix}`}>
          <slot></slot>
          {this.type && (
            <sup class={classes} style={style}>
              <slot name="content">
                {this.type === 'count' &&
                  (Number(this.count) > this.overflowCount ? `${this.overflowCount}+` : this.count)}
                {this.type === 'new' && t(badgeMessages.new)}
                {this.content && this.content}
              </slot>
              {this.disabled && <div class="disabled"></div>}
            </sup>
          )}
        </div>
      </Host>
    );
  }
}
